#!/usr/bin/env python3
"""Source for content/compose/kits/mathematics.json (numeric kits).

Run:  python3 content/compose/src/mathematics.py

Every config defines numbers (vars), derived values (derive), constraints and four options.
`ans` is the correct value; w1..w3 are values produced by a named misconception. Constraints keep
all displayed values distinct (after rounding), so exactly one option is ever correct.
Decision configs ("kind": "decision") instead give each option an `ok` expression; the engine
requires exactly one to be true for the drawn numbers.
An independent oracle in tests/compose-numeric-oracle.test.js recomputes every answer from the
drawn numbers with separately written JavaScript.
"""
import json, os, itertools

def I(lo, hi, step=1): return {"type": "int", "min": lo, "max": hi, "step": step}
def C(*vals): return {"type": "choice", "values": list(vals)}

def distinct(names, fn="round2"):
    return [f"{fn}({a}) != {fn}({b})" for a, b in itertools.combinations(names, 2)]

SAY = {}
def num(cid, level, principle, facts, prompt, vars, derive, cons, best, wrongs, lesson, fmt="money", rule="calculate-and-compare", modes=("decision",), why=None):
    """Numeric-answer config: best is (template, why); wrongs are (expr-name, template, why, mis).
    Option text is a short sentence: SAY[cid] + value (the instance validator requires 5+ words)."""
    say = SAY.get(cid, "The answer is")
    frame = lambda t: say + " " + t + "."
    opts = [{"key": "ans", "text": frame(best[0]), "ok": "1", "why": best[1], "mis": "-"}]
    for k, text, w, mis in wrongs:
        opts.append({"key": k, "text": frame(text), "ok": "0", "why": w, "mis": mis})
    names = ["ans"] + [w[0] for w in wrongs]
    return {"id": cid, "level": level, "principle": principle, "rule": rule, "kind": "numeric", "mode": list(modes),
            "facts": facts, "prompt": prompt, "vars": vars, "derive": derive,
            "constraints": cons + distinct(names), "options": opts, "lesson": lesson}

def dec(cid, level, principle, facts, prompt, vars, derive, cons, options, lesson, rule="calculate-and-compare"):
    return {"id": cid, "level": level, "principle": principle, "rule": rule, "kind": "decision", "mode": ["decision"],
            "facts": facts, "prompt": prompt, "vars": vars, "derive": derive, "constraints": cons,
            "options": [{"key": k, "text": t, "ok": ok, "why": w, "mis": m, **({"acceptable": True} if acc else {})}
                        for (k, t, ok, w, m, acc) in options], "lesson": lesson}

def find(cid, level, principle, facts, title, vars, derive, cons, lines, lesson, doc="note"):
    return {"id": cid, "level": level, "principle": principle, "rule": "find-calculation-error", "kind": "find", "mode": ["find"],
            "facts": facts, "prompt": ["Which line contains the calculation error?"], "title": [title], "docType": doc,
            "vars": vars, "derive": derive, "constraints": cons, "lines": lines, "lesson": lesson}

def line(lid, text, fine): return {"id": lid, "text": text, "fine": fine}
def badline(lid, text, why): return {"id": lid, "text": text, "bad": True, "why": why}

